<?php
function gl_show($value) { return $value === null || $value === '' ? '<span class="text-muted">Not recorded</span>' : nl2br(html_escape($value)); }
$types = array('poag' => 'Primary Open-Angle Glaucoma', 'pacg' => 'Primary Angle-Closure Glaucoma', 'ntg' => 'Normal Tension Glaucoma', 'secondary' => 'Secondary Glaucoma', 'congenital' => 'Congenital Glaucoma', 'suspect' => 'Glaucoma Suspect', 'oht' => 'Ocular Hypertension');
$risks = json_decode($record['risk_factors_json'], true); if (!is_array($risks)) { $risks = array(); }
$medications = json_decode($record['medications_json'], true); if (!is_array($medications)) { $medications = array(); }
?>
