        <div class="row"><div class="col-sm-4"><div class="box"><div class="box-body text-center"><span class="text-muted">Latest IOP OD</span><div class="gl-kpi <?php echo $record['latest_iop_od'] > $record['target_iop_od'] ? 'gl-high' : ''; ?>"><?php echo $record['latest_iop_od'] !== null ? $record['latest_iop_od'] . ' mmHg' : '-'; ?></div><small class="gl-target">Target <?php echo gl_show($record['target_iop_od']); ?></small></div></div></div><div class="col-sm-4"><div class="box"><div class="box-body text-center"><span class="text-muted">Latest IOP OS</span><div class="gl-kpi <?php echo $record['latest_iop_os'] > $record['target_iop_os'] ? 'gl-high' : ''; ?>"><?php echo $record['latest_iop_os'] !== null ? $record['latest_iop_os'] . ' mmHg' : '-'; ?></div><small class="gl-target">Target <?php echo gl_show($record['target_iop_os']); ?></small></div></div></div><div class="col-sm-4"><div class="box"><div class="box-body text-center"><span class="text-muted">Overall Status</span><div class="gl-kpi" style="font-size:20px"><?php echo ucwords(str_replace('_', ' ', html_escape($record['progression_status']))); ?></div><small>Next visit: <?php echo $record['next_visit'] ? date('d M Y', strtotime($record['next_visit'])) : 'Not scheduled'; ?></small></div></div></div></div>
        <div class="row"><div class="col-sm-6"><div class="box gl-detail-box"><div class="box-header"><h3 class="box-title">Optic Nerve Assessment</h3></div><div class="box-body"><table class="table table-bordered"><tr><th></th><th>OD</th><th>OS</th></tr><tr><td>Cup-to-Disc Ratio</td><td><?php echo gl_show($record['cdr_od']); ?></td><td><?php echo gl_show($record['cdr_os']); ?></td></tr><tr><td>Rim Thinning</td><td><?php echo gl_show(ucwords($record['rim_thinning_od'])); ?></td><td><?php echo gl_show(ucwords($record['rim_thinning_os'])); ?></td></tr><tr><td>Disc Hemorrhage</td><td><?php echo $record['disc_hemorrhage_od'] ? 'Yes' : 'No'; ?></td><td><?php echo $record['disc_hemorrhage_os'] ? 'Yes' : 'No'; ?></td></tr><tr><td>NFL Defect</td><td><?php echo $record['nfl_defect_od'] ? 'Yes' : 'No'; ?></td><td><?php echo $record['nfl_defect_os'] ? 'Yes' : 'No'; ?></td></tr></table></div></div></div><div class="col-sm-6"><div class="box gl-detail-box"><div class="box-header"><h3 class="box-title">Risk Factors & Notes</h3></div><div class="box-body"><p><strong>Family History:</strong> <?php echo $record['family_history'] ? 'Yes' : 'No'; ?></p><p><?php if ($risks) { foreach ($risks as $risk) { ?><span class="gl-tag"><?php echo ucwords(str_replace('_', ' ', html_escape($risk))); ?></span><?php } } else { ?><span class="text-muted">No significant risk factors documented</span><?php } ?></p><hr><strong>Clinical Notes</strong><p><?php echo gl_show($record['notes']); ?></p></div></div></div></div>
