        <div class="box gl-detail-box"><div class="box-header"><h3 class="box-title">Current Medications</h3></div><div class="box-body"><table class="table table-bordered"><thead><tr><th>Medication</th><th>Dosage</th><th>Frequency</th><th>Eye</th></tr></thead><tbody><?php if (!$medications) { ?><tr><td colspan="4" class="text-center text-muted">No current medications.</td></tr><?php } ?><?php foreach ($medications as $med) { ?><tr><td><?php echo html_escape($med['name']); ?></td><td><?php echo html_escape($med['dosage']); ?></td><td><?php echo strtoupper(html_escape($med['frequency'])); ?></td><td><?php echo html_escape($med['eye']); ?></td></tr><?php } ?></tbody></table></div></div>
